  /* 主题响应阴影 */
  box-shadow: var(--shadow-medium);

  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text-primary);
  overflow: hidden;
  box-sizing: border-box;
  transition: var(--transition);

  /* 容器内部间距 */
  padding: 6px;
}

/* 主界面 */
.main-interface {
  background: var(--surface-color);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow-medium);
  margin: 0; /* 移除外边距，使用容器的内边距 */
  overflow: hidden;
  border: 1px solid var(--border-color);
  position: relative;
}

/* 导航控制区域 */
.navigation-section {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  background: var(--navigation-background);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: var(--border-radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-medium);
  gap: 12px;
  min-height: 60px;
  transition: var(--transition);
}

.nav-btn {
  width: 44px;
  height: 44px;
  border: none;
  background: rgba(120, 120, 128, 0.16);
  border-radius: 50%;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  font-size: 20px;
  font-weight: bold;
  flex-shrink: 0;
}

.nav-btn:hover:not(:disabled) {
  background: var(--primary-color);
  color: white;
  transform: scale(var(--button-hover-scale));
}

.nav-btn:disabled {
  background: rgba(120, 120, 128, 0.08);
  color: rgba(120, 120, 128, 0.5);
  cursor: not-allowed;
  transform: none;
}

/* 下一个剧情按钮特殊样式 - 更明显 */
.next-btn,
#nextBtn {
  width: 56px;
  height: 44px;
  border-radius: 22px;
  background: var(--primary-color);
  color: white;
  font-size: 18px;
  flex-shrink: 0;
}

.next-btn:hover:not(:disabled),
#nextBtn:hover:not(:disabled) {
  background: var(--secondary-color);
  transform: scale(var(--button-hover-scale));
}

.next-btn:disabled,
#nextBtn:disabled {
  background: rgba(120, 120, 128, 0.16);
  color: rgba(120, 120, 128, 0.5);
}

/* 当前剧情显示区域 */
.current-story-display {
  flex: 1;
  padding: 8px 16px; /* 减少上下内边距 */
  cursor: pointer;
  transition: var(--transition);
  border-radius: var(--border-radius-small);
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

.current-story-display:hover {
  background: var(--background-color);
}

/* 未开始剧情状态样式 */
.current-story-display.no-plot {
  background: linear-gradient(135deg, rgba(255, 149, 0, 0.1) 0%, rgba(255, 149, 0, 0.05) 100%);
  border: 2px dashed rgba(255, 149, 0, 0.3);
  animation: pulse-border 2s ease-in-out infinite;
}

.current-story-display.no-plot:hover {
  background: linear-gradient(135deg, rgba(255, 149, 0, 0.15) 0%, rgba(255, 149, 0, 0.08) 100%);
  border-color: rgba(255, 149, 0, 0.5);
  transform: scale(1.02);
}

.current-story-display.no-plot .story-title {
  color: #ff9500;
  font-weight: 700;
  font-size: 18px;
}

.current-story-display.no-plot .story-status {
  color: #ff9500;
  font-weight: 600;
}

.current-story-display.no-plot .click-hint {
  color: #ff9500;
  font-weight: 500;
  opacity: 0.8;
  animation: blink 1.5s ease-in-out infinite;
}

/* 脉冲边框动画 */
@keyframes pulse-border {
  0%,
  100% {
    border-color: rgba(255, 149, 0, 0.3);
    box-shadow: 0 0 0 0 rgba(255, 149, 0, 0.1);
  }
  50% {
    border-color: rgba(255, 149, 0, 0.6);
    box-shadow: 0 0 0 4px rgba(255, 149, 0, 0.1);
  }
}

/* 闪烁提示动画 */
@keyframes blink {
  0%,
  100% {
    opacity: 0.8;
  }
  50% {
    opacity: 1;
  }
}

/* 标题与图标容器 */
.title-with-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* 标题和状态在同一行 */
.title-with-icon .story-title {
  margin-right: 12px;
}

.title-with-icon .story-status {
  margin: 0;
  flex-shrink: 0;
}

/* 未开始状态的图标 */
.no-plot-icon {
  font-size: 24px;
  color: #ff9500;
  animation: bounce 2s ease-in-out infinite;
  flex-shrink: 0;
}

@keyframes bounce {
  0%,
  20%,
  50%,
  80%,
  100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-5px);
  }
  60% {
    transform: translateY(-3px);
  }
}

.story-title-wrapper {
  text-align: center;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
  transition: var(--transition);
}

.story-title-wrapper:hover {
  background: rgba(0, 122, 255, 0.1);
}

.story-title {
  font-size: 20px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.3;
}

.story-status {
  font-size: 14px;
  font-weight: 500;
  margin: 0;
  white-space: nowrap;
}

.story-progress {
  font-size: 13px;
  font-weight: 500;
  margin: 4px 0 0 0;
  padding: 6px 12px;
  background: rgba(0, 122, 255, 0.1);
  border-radius: 8px;
  border-left: 3px solid var(--primary-color);
  color: var(--primary-color);
  line-height: 1.3;
}

/* 状态和进度的联合显示容器 */
.story-status-container {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  justify-content: center;
  margin-top: 4px;
  width: 100%;
}

.story-status-container .story-progress {
  margin: 0;
  flex: 1;
  min-width: 200px;
}

/* 小屏幕下的优化 */
@media (max-width: 480px) {
  .story-status-container {
    flex-direction: column;
    gap: 4px;
  }

  .story-status-container .story-progress {
    min-width: auto;
    width: 100%;
  }
}

.click-hint {
  font-size: 12px;
  color: var(--text-secondary);
  opacity: 0.6;
  margin: 0;
  font-style: italic;
  transition: var(--transition);
}

.current-story-display:hover .click-hint {
  opacity: 0.8;
}

/* 回到当前剧情按钮 */
.back-to-current-btn {
  width: 32px;
  height: 32px;
  border: none;
  background: var(--primary-color);
  border-radius: 50%;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 14px;
  box-shadow: 0 2px 8px rgba(0, 122, 255, 0.3);
  flex-shrink: 0;
  margin-left: 8px;
}

.back-to-current-btn:hover {
  background: #0056cc;
  transform: scale(1.1);
  box-shadow: 0 4px 12px rgba(0, 122, 255, 0.4);
}

.back-to-current-btn:active {
  transform: scale(0.95);
}

/* 操作按钮区域 */
.action-buttons {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.action-btn {
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 20px;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  background: rgba(120, 120, 128, 0.16);
  color: var(--text-primary);
}

.action-btn:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.05);
}

.action-btn.primary {
  background: var(--primary-color);
  color: white;
}

.action-btn.primary:hover {
  background: #0056cc;
  transform: scale(1.05);
}

/* 主要按钮样式 */
.control-btn.primary {
  background: var(--primary-color);
  color: white;
  box-shadow: var(--shadow-light);
}

.control-btn.primary:hover {
  background: #0056cc;
  transform: translateY(-1px);
  box-shadow: var(--shadow-medium);
}

.control-btn.primary:active {
  transform: translateY(0);
  background: #004499;
}

/* 次要按钮样式 */
.control-btn.secondary {
  background: var(--background-color);
  color: var(--primary-color);
  border: 1px solid var(--border-color);
}

.control-btn.secondary:hover {
  background: #e5e5ea;
  transform: translateY(-1px);
}

.control-btn.secondary:active {
  transform: translateY(0);
  background: #d1d1d6;
}

/* 禁用状态 */
.control-btn:disabled {
  background: var(--border-color) !important;
  color: var(--text-secondary) !important;
  cursor: not-allowed !important;
  transform: none !important;
  box-shadow: none !important;
}

/* 按钮图标 */
.btn-icon {
  font-size: 18px;
  line-height: 1;
}

/* 弹出面板通用样式 - 向上弹出的iPhone风格 */
.popup-panel {
  background: var(--surface-color);
  border-radius: var(--border-radius);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
  margin: 0 0 2px 0; /* 进一步减少边距 */
  border: 0.5px solid rgba(0, 0, 0, 0.1);
  overflow: hidden;
  backdrop-filter: blur(20px);
  transform-origin: bottom;
  /* 默认隐藏在下方 */
  transform: translateY(20px) scaleY(0.8);
  opacity: 0;
  transition: none; /* 移除动画效果 */
  max-height: 0;
}

/* 显示状态的弹出面板 */
.popup-panel.show {
  transform: translateY(0) scaleY(1);
  opacity: 1;
  max-height: calc(100vh - 100px); /* 为导航区域留出空间 */
}

/* 剧情详情面板特殊高度设置 */
.story-detail-section.popup-panel.show {
  max-height: calc(100vh - 80px); /* 剧情详情需要更多空间 */
}

/* 小屏幕下的弹出面板 - 允许更大高度 */
@media (max-width: 480px) {
  .popup-panel {
    margin: 0; /* 小屏幕下无边距，充分利用空间 */
  }

  .popup-panel.show {
    max-height: calc(100vh - 120px); /* 留出导航区域的空间 */
  }

  /* 剧情详情面板在小屏幕下显示更多内容 */
  .story-detail-section.popup-panel.show {
    max-height: calc(100vh - 60px);
  }

  .story-detail-section .detail-content {
    max-height: calc(100vh - 120px);
  }
}

/* 展开区域通用样式 - iPhone风格（继承popup-panel样式） */

.section-header {
  padding: 12px 16px;
  background: rgba(248, 248, 248, 0.95);
  backdrop-filter: blur(20px);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-header h3 {
  font-size: 16px;
  font-weight: 600;
  margin: 0;
  color: var(--text-primary);
}

.header-buttons {
  display: flex;
  gap: 8px;
  align-items: center;
}

.sort-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: rgba(120, 120, 128, 0.16);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 600;
}

.sort-btn:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.05);
}

.sort-btn.asc .btn-icon::after {
  content: '↑';
}

.sort-btn.desc .btn-icon::after {
  content: '↓';
}

.close-section-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: rgba(120, 120, 128, 0.16);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 600;
}

.close-section-btn:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.05);
}

/* 剧情列表区域 */
.story-list-container {
  max-height: 240px; /* 约3个选项的高度 */
  overflow-y: auto;
  padding: 8px 12px 12px;
}

/* 剧情列表项 - iPhone风格 */
.story-item {
  padding: 8px 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: var(--transition);
  margin-bottom: 4px;
  border: none;
  background: rgba(120, 120, 128, 0.08);
}

.story-item:hover {
  background: rgba(0, 122, 255, 0.1);
  transform: scale(1.01);
}

.story-item.current {
  background: rgba(0, 122, 255, 0.15);
  border: 1px solid var(--primary-color);
}

.story-item-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.story-item-title {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
  line-height: 1.2;
  color: var(--text-primary);
}

.story-item-location {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1.2;
}

.story-item-progress {
  font-size: 11px;
  color: var(--primary-color);
  font-weight: 500;
  margin: 0;
  line-height: 1.2;
}

/* 剧情详情区域 - iPhone风格 */
.detail-content {
  padding: 16px;
  background: var(--surface-color);
  max-height: 450px;
  overflow-y: auto;
}

/* 设置面板样式 */
.settings-content {
  padding: 16px;
  background: var(--surface-color);
}

/* 旧的内联按钮样式 - 已废弃，改用顶部按钮 */
.detail-actions-inline {
  display: none !important; /* 隐藏旧的底部按钮 */
}

/* 旧的内联按钮子样式 - 已废弃 */

/* 顶部操作按钮区域 - 彻底解决遮挡问题 */
.detail-actions-top {
  padding: 16px;
  background: rgba(248, 248, 248, 0.98);
  backdrop-filter: blur(20px);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
  display: flex;
  gap: 12px;
  justify-content: center;
  /* 确保按钮始终可见 */
  position: relative;
  z-index: 1;
}

.detail-actions-top .detail-btn {
  flex: 1;
  max-width: 140px;
  height: 40px;
  border: none;
  border-radius: 20px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.detail-actions-top .detail-btn.secondary {
  background: rgba(120, 120, 128, 0.16);
  color: var(--text-primary);
}

.detail-actions-top .detail-btn.secondary:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.02);
}

.detail-actions-top .detail-btn.primary {
  background: var(--primary-color);
  color: white;
}

.detail-actions-top .detail-btn.primary:hover {
  background: #0056cc;
  transform: scale(1.02);
}

.setting-item {
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.setting-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.setting-item label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.setting-item select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--surface-color);
  font-size: 16px;
  color: var(--text-primary);
}

.reset-all-btn {
  width: 100%;
  padding: 12px 20px;
  margin-top: 8px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, #ff3b30 0%, #ff6b6b 100%);
  color: white;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 2px 8px rgba(255, 59, 48, 0.3);
}

.reset-all-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(255, 59, 48, 0.4);
  background: linear-gradient(135deg, #ff2d22 0%, #ff5555 100%);
}

.reset-all-btn:active {
  transform: translateY(0);
  box-shadow: 0 1px 4px rgba(255, 59, 48, 0.3);
}

.reset-all-btn .btn-icon {
  font-size: 16px;
}

.setting-item input[type='checkbox'] {
  margin-right: 8px;
  transform: scale(1.2);
}

.setting-item span {
  font-size: 16px;
  color: var(--text-primary);
}

.setting-description {
  margin-top: 6px;
}

.setting-description small {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
  display: block;
  font-style: italic;
}

/* 基础详情项样式 */
.detail-item {
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.detail-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.detail-item label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  margin-bottom: 4px;
}

.detail-item span,
.detail-item div {
  font-size: 16px;
  color: var(--text-primary);
  line-height: 1.5;
  word-wrap: break-word;
}

/* 短内容项目 - 单行显示 */
.detail-item.inline {
  display: flex;
  align-items: flex-start;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.15);
}

.detail-item.inline label {
  flex-shrink: 0;
  width: 85px;
  margin-bottom: 0;
  margin-right: 12px;
  font-size: 13px;
}

.detail-item.inline span {
  flex: 1;
  font-size: 15px;
  line-height: 1.4;
}

/* 长内容项目 - 块级显示 */
.detail-item.block {
  margin-bottom: 14px;
  padding-bottom: 10px;
}

.detail-item.block label {
  margin-bottom: 6px;
  font-size: 13px;
}

.detail-item.block div {
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
}

/* 组合显示 - 将多个短项目放在一行 */
.detail-row {
  display: flex;
  gap: 20px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.detail-row .detail-item {
  flex: 1;
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
  min-width: 0;
}

.detail-row .detail-item label {
  margin-bottom: 4px;
  font-size: 13px;
}

.detail-row .detail-item span {
  font-size: 15px;
  word-break: break-word;
  line-height: 1.4;
}

/* 旧的 detail-actions 和 detail-btn 样式已被 detail-actions-inline 替代 */

/* 确认对话框样式 */
.confirmation-dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  min-height: 100vh; /* 确保至少占满视口 */
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  overflow: auto; /* 允许滚动以防内容过大 */
  padding: 20px 10px; /* 增加内边距确保弹框不会贴边 */
}

.confirmation-dialog-overlay.show {
  opacity: 1;
}

.confirmation-dialog {
  background: var(--surface-color);
  border-radius: 12px;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.3);
  width: 85%;
  max-width: 280px;
  overflow: hidden;
  transform: scale(0.9) translateY(20px);
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  margin: auto; /* 确保居中 */
  position: relative;
}

.confirmation-dialog-overlay.show .confirmation-dialog {
  transform: scale(1) translateY(0);
}

.dialog-header {
  padding: 14px 16px 10px;
  text-align: center;
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
}

.dialog-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}

.dialog-content {
  padding: 12px 16px;
  text-align: center;
  max-height: 120px;
  overflow-y: auto;
}

.dialog-message {
  margin: 0;
  font-size: 14px;
  color: var(--text-primary);
  line-height: 1.4;
}

.dialog-options {
  padding: 10px 16px;
  border-top: 0.5px solid rgba(0, 0, 0, 0.1);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
}

.checkbox-option {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-primary);
  user-select: none;
}

.checkbox-option input[type='checkbox'] {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: var(--surface-color);
  cursor: pointer;
  position: relative;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
}

.checkbox-option input[type='checkbox']:checked {
  background: var(--primary-color);
  border-color: var(--primary-color);
}

.checkbox-option input[type='checkbox']:checked::after {
  content: '✓';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: white;
  font-size: 11px;
  font-weight: bold;
}

.dialog-actions {
  display: flex;
  gap: 0;
}

.dialog-btn {
  flex: 1;
  padding: 12px;
  border: none;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  background: transparent;
}

.dialog-btn:not(:last-child) {
  border-right: 0.5px solid rgba(0, 0, 0, 0.1);
}

.dialog-btn.secondary {
  color: var(--text-primary);
}

.dialog-btn.secondary:hover {
  background: rgba(0, 0, 0, 0.05);
}

.dialog-btn.primary {
  color: var(--primary-color);
  font-weight: 700;
}

.dialog-btn.primary:hover {
  background: rgba(0, 122, 255, 0.1);
}

.dialog-btn:active {
  transform: scale(0.98);
}

/* 小屏幕下的对话框优化 */
@media (max-width: 480px) {
  .confirmation-dialog {
    width: 90%;
    max-width: 260px;
  }

  .dialog-header {
    padding: 12px 14px 10px;
  }

  .dialog-title {
    font-size: 14px;
  }

  .dialog-content {
    padding: 10px 14px;
    max-height: 100px;
  }

  .dialog-message {
    font-size: 13px;
  }

  .dialog-options {
    padding: 8px 14px;
  }

  .checkbox-option {
    font-size: 12px;
  }

  .dialog-btn {
    padding: 10px;
    font-size: 14px;
  }
}

/* 反馈消息 */
.feedback-message {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--text-primary);
  color: white;
  padding: 12px 20px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 500;
  opacity: 0;
  transition: var(--transition);
  z-index: 1001;
  box-shadow: var(--shadow-medium);
}

.feedback-message.show {
  opacity: 1;
}

/* 中等屏幕样式 (481px - 767px) */
@media (min-width: 481px) and (max-width: 767px) {
  /* 旧的中等屏幕内联按钮样式 - 已废弃 */

  /* 中等屏幕顶部按钮样式 */
  .detail-actions-top {
    padding: 16px;
    flex-direction: column;
    gap: 12px;
  }

  .detail-actions-top .detail-btn {
    height: 48px;
    max-width: none;
    width: 100%;
    font-size: 16px;
    font-weight: 600;
    border-radius: 12px;
  }
}

/* 大屏幕桌面端按钮样式 (768px+) */
@media (min-width: 768px) {
  /* 旧的大屏幕内联按钮样式 - 已废弃 */

  /* 大屏幕顶部按钮样式 */
  .detail-actions-top {
    padding: 16px;
    flex-direction: row;
    gap: 16px;
    justify-content: center;
  }

  .detail-actions-top .detail-btn {
    height: 40px;
    max-width: 140px;
    width: auto;
    flex: 1;
    font-size: 15px;
    font-weight: 600;
    border-radius: 20px;
  }
}

/* 响应式设计 - 移动端优先 */

/* 650px以下 - 小屏手机 */
@media (max-width: 650px) {
  /* 容器样式优化 */
  .story-assistant-container {
    padding: 4px;
    border-radius: var(--border-radius-small);
    max-width: 100%;
  }

  .main-interface,
  .story-list-section,
  .story-detail-section,
  .settings-section {
    margin: 0;
    border-radius: var(--border-radius-small);
  }

  /* 导航栏 - 流式布局 */
  .navigation-section {
    padding: 6px 8px;
    min-height: auto;
    gap: 6px;
    flex-wrap: wrap;
    justify-content: center;
  }

  /* 按钮尺寸优化 */
  .nav-btn {
    width: 38px;
    height: 38px;
    font-size: 16px;
    flex-shrink: 0;
  }

  #nextBtn,
  .next-btn {
    width: 48px;
    height: 38px;
    font-size: 16px;
  }

  /* 当前剧情显示区 - 流式布局 */
  .current-story-display {
    flex: 1 1 100%;
    order: -1;
    padding: 8px;
    margin-bottom: 6px;
    min-width: 0;
  }

  .story-title-wrapper {
    width: 100%;
    padding: 4px;
  }

  .story-title {
    font-size: 16px;
    line-height: 1.4;
    word-break: break-word;
  }

  .story-status {
    font-size: 13px;
  }

  .story-progress {
    font-size: 12px;
    padding: 4px 8px;
    margin-top: 4px;
  }

  /* 操作按钮区 */
  .action-buttons {
    gap: 4px;
    flex-shrink: 0;
  }

  .action-btn {
    width: 34px;
    height: 34px;
    font-size: 14px;
  }

  /* 弹出面板优化 */
  .popup-panel.show {
    max-height: 70vh;
  }

  .story-detail-section.popup-panel.show {
    max-height: 75vh;
  }

  /* 列表容器 */
  .story-list-container {
    max-height: 50vh;
    padding: 6px 8px 8px;
  }

  .story-item {
    padding: 10px;
    margin-bottom: 6px;
  }

  .story-item-title {
    font-size: 15px;
    word-break: break-word;
  }

  .story-item-location {
    font-size: 13px;
  }

  /* 详情内容 */
  .detail-content {
    padding: 12px;
    max-height: 65vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    scroll-behavior: smooth;
  }

  .detail-item.compact {
    margin-bottom: 10px;
  }

  .detail-item.compact label {
    font-size: 12px;
  }

  .detail-item.compact div {
    font-size: 14px;
    word-break: break-word;
  }

  /* 步骤列表 */
  .steps-title {
    font-size: 16px;
    margin-bottom: 12px;
  }

  .step-item {
    flex-direction: column;
    gap: 8px;
    padding: 12px;
  }

  .step-header-line {
    width: 100%;
  }

  .step-characters-inline {
    font-size: 13px;
    word-break: break-word;
  }

  .step-event-line {
    font-size: 14px;
    word-break: break-word;
  }

  .step-actions {
    width: 100%;
    justify-content: stretch;
  }

  .step-execute-btn {
    width: 100%;
    padding: 10px;
    font-size: 15px;
    justify-content: center;
  }

  /* 详情顶部按钮 */
  .detail-actions-top {
    padding: 12px;
    flex-direction: column;
    gap: 10px;
  }

  .detail-actions-top .detail-btn {
    height: 44px;
    max-width: none;
    width: 100%;
    font-size: 15px;
    border-radius: 10px;
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
  }

  /* 设置面板 */
  .settings-content {
    padding: 12px;
    max-height: 65vh;
    overflow-y: auto;
  }

  .setting-item {
    margin-bottom: 14px;
    padding-bottom: 10px;
  }

  .setting-item label {
    font-size: 14px;
  }

  .setting-item select {
    font-size: 15px;
    padding: 10px;
  }

  /* 详情布局流式化 */
  .detail-row {
    flex-direction: column;
    gap: 8px;
  }

  .detail-row .detail-item {
    flex: none;
  }

  .detail-item.inline {
    flex-direction: column;
    align-items: flex-start;
  }

  .detail-item.inline label {
    width: auto;
    margin-right: 0;
    margin-bottom: 4px;
  }

  /* 回到当前剧情按钮 */
  .back-to-current-btn {
    width: 30px;
    height: 30px;
    font-size: 13px;
    margin-left: 4px;
  }

  /* 反馈消息 */
  .feedback-message {
    top: 10px;
    padding: 10px 16px;
    font-size: 13px;
    border-radius: 16px;
    max-width: 90%;
  }

  /* 对话框优化 */
  .confirmation-dialog {
    width: 92%;
    max-width: 320px;
  }

  .dialog-title {
    font-size: 15px;
  }

  .dialog-message {
    font-size: 14px;
  }

  .dialog-btn {
    padding: 12px;
    font-size: 15px;
  }
}

/* 481px-650px - 中等屏幕 */
@media (min-width: 481px) and (max-width: 650px) {
  .navigation-section {
    padding: 8px 12px;
    gap: 8px;
  }

  .nav-btn {
    width: 42px;
    height: 42px;
  }

  #nextBtn,
  .next-btn {
    width: 52px;
    height: 42px;
  }

  .story-title {
    font-size: 18px;
  }

  .action-btn {
    width: 38px;
    height: 38px;
  }

  .detail-actions-top {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 12px;
  }

  .detail-actions-top .detail-btn {
    flex: 1 1 calc(50% - 6px);
    min-width: 120px;
    height: 42px;
  }
}

/* 480px以下 - 超小屏 */
@media (max-width: 480px) {
  .story-assistant-container {
    padding: 3px;
  }

  .navigation-section {
    padding: 6px;
  }

  .nav-btn {
    width: 36px;
    height: 36px;
    font-size: 15px;
  }

  #nextBtn,
  .next-btn {
    width: 46px;
    height: 36px;
  }

  .current-story-display {
    padding: 6px;
  }

  .story-title {
    font-size: 15px;
  }

  .story-status {
    font-size: 12px;
  }

  .action-btn {
    width: 32px;
    height: 32px;
    font-size: 13px;
  }

  .story-item {
    padding: 8px;
  }

  .detail-content {
    padding: 10px;
  }

  .step-item {
    padding: 10px;
  }

  .detail-actions-top {
    padding: 10px;
  }

  .detail-actions-top .detail-btn {
    height: 42px;
    font-size: 14px;
  }
}

/* 滚动条美化 - iPhone风格 */
.story-list-container::-webkit-scrollbar,
.detail-content::-webkit-scrollbar {
  width: 4px;
}

.story-list-container::-webkit-scrollbar-track,
.detail-content::-webkit-scrollbar-track {
  background: transparent;
}

.story-list-container::-webkit-scrollbar-thumb,
.detail-content::-webkit-scrollbar-thumb {
  background: rgba(120, 120, 128, 0.3);
  border-radius: 2px;
}

.story-list-container::-webkit-scrollbar-thumb:hover,
.detail-content::-webkit-scrollbar-thumb:hover {
  background: rgba(120, 120, 128, 0.5);
}

/* 动画增强 */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 弹出面板动画 - 从下方向上滑入 */
@keyframes popupSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scaleY(0.8);
    max-height: 0;
  }
  to {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: calc(100vh - 80px);
  }
}

/* 弹出面板隐藏动画 - 向下滑出 */
@keyframes popupSlideDown {
  from {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: calc(100vh - 80px);
  }
  to {
    opacity: 0;
    transform: translateY(20px) scaleY(0.8);
    max-height: 0;
  }
}

.main-interface {
  animation: fadeInUp 0.5s ease-out;
}

/* 无障碍支持 */
.control-btn:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.story-item:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* 剧情详情样式 */
.story-info-section {
  margin-bottom: 16px;
  background: linear-gradient(135deg, rgba(0, 122, 255, 0.05) 0%, rgba(88, 86, 214, 0.05) 100%);
  border-radius: var(--border-radius-small);
  padding: 12px 14px;
  border: 1px solid rgba(0, 122, 255, 0.1);
}

/* 返回列表按钮样式 */
.back-to-list-btn {
  width: 32px;
  height: 32px;
  border: none;
  background: rgba(120, 120, 128, 0.2);
  border-radius: 16px;
  color: var(--text-primary);
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  margin-right: 8px;
}

.back-to-list-btn:hover {
  background: rgba(120, 120, 128, 0.3);
  transform: scale(1.05);
}

/* 压缩的详情项样式 */
.detail-item {
  margin-bottom: 0;
  padding: 0;
  border-bottom: none;
}

.detail-item + .detail-item {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(0, 122, 255, 0.1);
}

.detail-item.compact {
  margin-bottom: 0;
  padding-bottom: 0;
}

.detail-item.compact label {
  display: none;
}

.detail-item.compact div {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.5;
  font-weight: 400;
}

.detail-item.compact div strong {
  color: var(--primary-color);
  font-weight: 700;
  margin-right: 6px;
}

.steps-section {
  margin-top: 20px;
}

.steps-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 16px;
  padding-left: 12px;
  border-left: 3px solid var(--primary-color);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.steps-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* 步骤项样式 */
/* 步骤项 - 全新卡片式设计 */
.step-item {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0;
  background: var(--surface-color);
  border-radius: 12px;
  border: 2px solid #e8e8ed;
  overflow: hidden;
  transition: var(--transition);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-item:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  border-color: var(--primary-color);
}

.step-item.executed {
  border-color: var(--success-color);
}

.step-item.pending {
  border-color: #a99de8;
}

/* 步骤头部 - 紧凑设计 */
.step-header-line {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
  border-bottom: 1px solid #e8e8ed;
}

.step-item.executed .step-header-line {
  background: linear-gradient(135deg, rgba(52, 199, 89, 0.1) 0%, rgba(52, 199, 89, 0.05) 100%);
}

.step-item.pending .step-header-line {
  background: linear-gradient(135deg, rgba(139, 127, 214, 0.1) 0%, rgba(139, 127, 214, 0.05) 100%);
}

.step-id {
  font-size: 11px;
  font-weight: 700;
  color: var(--primary-color);
  background: rgba(0, 122, 255, 0.1);
  padding: 4px 10px;
  border-radius: 12px;
  white-space: nowrap;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.step-item.executed .step-id {
  color: var(--success-color);
  background: rgba(52, 199, 89, 0.15);
}

.step-item.pending .step-id {
  color: #8b7fd6;
  background: rgba(139, 127, 214, 0.15);
}

/* 步骤内容区 */
.step-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 12px;
}

/* 步骤地点字段 */
.step-location-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
}

.location-label {
  font-size: 14px;
  flex-shrink: 0;
}

.step-location-input {
  flex: 1;
  padding: 4px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  transition: var(--transition);
  min-width: 100px;
}

.step-location-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(0, 122, 255, 0.1);
}

/* 紧凑字段容器 */
.step-field-compact {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* 内联标签 */
.inline-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary);
  display: inline-block;
}

/* 角色编辑器 */
.characters-editor {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.character-item {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 8px;
  background: rgba(88, 86, 214, 0.03);
  border-radius: 6px;
  border: 1px solid rgba(88, 86, 214, 0.1);
}

/* 角色字段 */
.char-field {
  display: flex;
  align-items: center;
  gap: 6px;
}

.char-field.full-width {
  grid-column: 1 / 3;
}

.char-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--secondary-color);
  white-space: nowrap;
  flex-shrink: 0;
}

.char-name-input,
.char-mood-input,
.char-thoughts-input {
  flex: 1;
  padding: 5px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 5px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  transition: var(--transition);
}

.char-name-input {
  font-weight: 600;
}

.char-name-input:focus,
.char-mood-input:focus,
.char-thoughts-input:focus {
  outline: none;
  border-color: var(--secondary-color);
  box-shadow: 0 0 0 2px rgba(88, 86, 214, 0.1);
}

.no-characters {
  padding: 12px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 12px;
  font-style: italic;
}

/* 事件描述输入 - 2行textarea */
.step-event-input {
  padding: 6px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  resize: vertical;
  font-family: inherit;
  line-height: 1.5;
  transition: var(--transition);
  width: 100%;
}

.step-event-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(0, 122, 255, 0.1);
}

/* 剧情发展输入 - 单行input */
.step-development-input {
  padding: 5px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  transition: var(--transition);
  width: 100%;
}

.step-development-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(0, 122, 255, 0.1);
}

.step-execute-btn {
  padding: 6px 14px;
  border: none;
  border-radius: 16px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  min-width: auto;
  white-space: nowrap;
}

.step-execute-btn .btn-icon {
  font-size: 14px;
}

.step-execute-btn.pending {
  background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);
  color: white;
  box-shadow: 0 2px 8px rgba(0, 122, 255, 0.3);
}

.step-execute-btn.pending:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 122, 255, 0.4);
}

.step-execute-btn.executed {
  background: linear-gradient(135deg, var(--success-color) 0%, #28a745 100%);
  color: white;
  box-shadow: 0 2px 8px rgba(52, 199, 89, 0.3);
}

.step-execute-btn.executed:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(52, 199, 89, 0.4);
}

.step-execute-btn:active {
  transform: translateY(0);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
}

/* 主题特定增强样式 */

/* 女性化可爱系主题增强 */
[data-theme='cute'] .story-assistant-container {
  background: var(--accent-gradient);
