 */
async function getCurrentCharacterPrimaryWorldbook() {
  try {
    const charWorldbooks = getCharWorldbookNames('current');
    if (!charWorldbooks.primary) {
      return null;
    }
    const primaryWorldbookName = charWorldbooks.primary,
      worldbookEntries = await getWorldbook(primaryWorldbookName);
    return worldbookEntries;
  } catch (error) {
    return window.simpleLog('获取世界书', '获取当前角色主要世界书内容时发生错误', error, error.message), null;
  }
}

/**
 * 从世界书中获取剧情元数据
 * @returns {Promise<Object|null>} 剧情数据对象或null
 */
async function getPlotDataFromWorldbook() {
  try {
    console.log('🔍 生产环境：开始从世界书获取剧情数据');

    // 1. 获取当前角色的主要世界书
    const worldbookEntries = await getCurrentCharacterPrimaryWorldbook();
    if (!worldbookEntries) {
      throw new Error('无法获取当前角色的主要世界书');
    }

    console.log(`📚 生产环境：获取到 ${worldbookEntries.length} 个世界书条目`);

    // 2. 查找包含指定文本的条目
    const targetEntry = worldbookEntries.find(entry => entry.name.includes('剧情元数据-By萧谴剧情模拟器'));

    if (!targetEntry) {
      throw new Error('未找到名为"剧情元数据-By萧谴剧情模拟器"的世界书条目');
    }

    console.log('✅ 生产环境：找到目标世界书条目');
    console.log('📝 生产环境：条目内容长度:', targetEntry.content.length);

    // 3. 提取JSON内容（兼容两种格式）
    let jsonContent = targetEntry.content.trim();

    // 检查是否包含 [plotResultStart] 和 [plotResultEnd] 标记
    const startMarker = '[plotResultStart]';
    const endMarker = '[plotResultEnd]';

    if (jsonContent.includes(startMarker) && jsonContent.includes(endMarker)) {
      console.log('📋 生产环境：检测到标记格式，提取JSON内容');
      const startIndex = jsonContent.indexOf(startMarker) + startMarker.length;
      const endIndex = jsonContent.indexOf(endMarker);
      jsonContent = jsonContent.substring(startIndex, endIndex).trim();
      console.log('✅ 生产环境：成功提取标记内的JSON内容');
    } else {
      console.log('📋 生产环境：未检测到标记，假定为直接JSON格式');
    }

    // 4. 尝试解析JSON内容
    let plotData;
    try {
      plotData = JSON.parse(jsonContent);
      console.log('✅ 生产环境：JSON解析成功');
    } catch (jsonError) {
      console.error('❌ JSON解析失败，内容预览:', jsonContent.substring(0, 200));
      throw new Error(`JSON解析失败: ${jsonError.message}`);
    }

    // 5. 验证数据格式（基础验证）
    if (!plotData || typeof plotData !== 'object') {
      throw new Error('解析的数据不是有效的对象');
    }

    if (!plotData.hasOwnProperty('currentPlot') || !plotData.hasOwnProperty('plotList')) {
      throw new Error('数据格式不符合要求：缺少 currentPlot 或 plotList 字段');
    }

    console.log('✅ 生产环境：数据格式验证通过');
    console.log('📊 生产环境：currentPlot =', plotData.currentPlot);
    console.log('📚 生产环境：plotList 数组长度 =', plotData.plotList?.length || 0);

    return plotData;
  } catch (error) {
    console.error('❌ 生产环境：获取剧情数据失败:', error.message);
    return { error: error.message };
  }
}

/**
 * 生产环境初始化
 * @returns {Promise<Object>} 包含数据或错误信息的对象
 */
async function initProductionEnvironment() {
  console.log('🚀 生产环境：开始初始化');

  try {
    // 检查必要的API是否可用
    if (typeof getCharWorldbookNames === 'undefined' || typeof getWorldbook === 'undefined') {
      throw new Error('世界书API不可用，可能不在支持的环境中运行');
    }

    // 获取剧情数据
    const plotData = await getPlotDataFromWorldbook();

    if (plotData && plotData.error) {
      // 数据获取失败，返回错误信息
      return {
        success: false,
        error: plotData.error,
        data: null,
      };
    }

    // 成功获取数据
    console.log('🎉 生产环境：初始化完成');
    return {
      success: true,
      error: null,
      data: plotData,
    };
  } catch (error) {
    console.error('💥 生产环境：初始化失败:', error.message);
    return {
      success: false,
      error: `生产环境初始化失败: ${error.message}`,
      data: null,
    };
  }
}

