  /**
   * 显示生产环境错误
   */
  function showProductionError(title, message) {
    console.error('🚨 生产环境错误:', title, '-', message);

    // 显示错误状态
    showNoPlotState(`生产环境错误: ${title}`, `生产环境数据加载失败，请检查世界书配置`);

    // 显示持久错误消息
    const fullErrorMsg = `🚨 生产环境错误\n\n标题: ${title}\n详情: ${message}\n\n请检查：\n1. 是否有名为"剧情元数据-By萧谴剧情模拟器"的世界书条目\n2. 条目内容是否为有效的JSON格式\n3. JSON数据是否包含 currentPlot 和 plotList 字段`;

    showFeedback(fullErrorMsg);

    // 启动重试机制：每隔5秒重试一次，连续重试3次
    startRetryMechanism();
  }

  /**
   * 重试机制：每隔5秒重试一次，连续重试3次
   */
  let retryCount = 0;
  let retryTimer = null;
  const MAX_RETRY_COUNT = 3;
  const RETRY_INTERVAL = 5000; // 5秒

  function startRetryMechanism() {
    // 清除之前的重试定时器（如果存在）
    if (retryTimer) {
      clearTimeout(retryTimer);
    }

    retryCount = 0;
    console.log('🔄 启动重试机制：将每隔5秒重试一次，最多重试3次');

    // 启动第一次重试
    scheduleRetry();
  }

  function scheduleRetry() {
    if (retryCount >= MAX_RETRY_COUNT) {
      console.error('❌ 已达到最大重试次数，停止重试');
      showFeedback(`已重试 ${MAX_RETRY_COUNT} 次，仍无法加载数据。请检查世界书配置。`);
      return;
    }

    retryCount++;
    console.log(`⏰ 准备第 ${retryCount} 次重试，将在 ${RETRY_INTERVAL / 1000} 秒后执行...`);

    showFeedback(`第 ${retryCount} 次重试将在 ${RETRY_INTERVAL / 1000} 秒后开始...`);

    retryTimer = setTimeout(async () => {
      console.log(`🔄 执行第 ${retryCount} 次重试...`);
      showFeedback(`正在执行第 ${retryCount} 次重试...`);

      try {
        // 重新尝试加载数据
        await processPlotDataForProduction();
      } catch (error) {
        console.error(`❌ 第 ${retryCount} 次重试失败:`, error);

        // 如果还有重试次数，继续重试
        if (retryCount < MAX_RETRY_COUNT) {
          scheduleRetry();
        } else {
          console.error('❌ 已达到最大重试次数，停止重试');
          showFeedback(`已重试 ${MAX_RETRY_COUNT} 次，仍无法加载数据。请检查世界书配置。`);
        }
      }
    }, RETRY_INTERVAL);
  }

  /**
   * 停止重试机制
   */
  function stopRetryMechanism() {
    if (retryTimer) {
      clearTimeout(retryTimer);
      retryTimer = null;
    }
    retryCount = 0;
    console.log('⏹️ 重试机制已停止');
  }

  /**
   * 加载默认数据（备用）
   */
  function loadDefaultData() {
