}

.detail-actions-top .detail-btn {
  flex: 1;
  max-width: 140px;
  height: 40px;
  border: none;
  border-radius: 20px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.detail-actions-top .detail-btn.secondary {
  background: rgba(120, 120, 128, 0.16);
  color: var(--text-primary);
}

.detail-actions-top .detail-btn.secondary:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.02);
}

.detail-actions-top .detail-btn.primary {
  background: var(--primary-color);
  color: white;
}

.detail-actions-top .detail-btn.primary:hover {
  background: #0056cc;
  transform: scale(1.02);
}

.setting-item {
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.setting-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.setting-item label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.setting-item select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--surface-color);
  font-size: 16px;
  color: var(--text-primary);
}

.reset-all-btn {
  width: 100%;
  padding: 12px 20px;
  margin-top: 8px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, #ff3b30 0%, #ff6b6b 100%);
  color: white;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 2px 8px rgba(255, 59, 48, 0.3);
}

.reset-all-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(255, 59, 48, 0.4);
  background: linear-gradient(135deg, #ff2d22 0%, #ff5555 100%);
}

.reset-all-btn:active {
  transform: translateY(0);
  box-shadow: 0 1px 4px rgba(255, 59, 48, 0.3);
}

.reset-all-btn .btn-icon {
  font-size: 16px;
}

.setting-item input[type='checkbox'] {
  margin-right: 8px;
  transform: scale(1.2);
}

.setting-item span {
  font-size: 16px;
  color: var(--text-primary);
}

.setting-description {
  margin-top: 6px;
}

.setting-description small {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
  display: block;
  font-style: italic;
}

/* 基础详情项样式 */
.detail-item {
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.detail-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.detail-item label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  margin-bottom: 4px;
}

.detail-item span,
.detail-item div {
  font-size: 16px;
  color: var(--text-primary);
  line-height: 1.5;
  word-wrap: break-word;
}

/* 短内容项目 - 单行显示 */
.detail-item.inline {
  display: flex;
  align-items: flex-start;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.15);
}

.detail-item.inline label {
  flex-shrink: 0;
  width: 85px;
  margin-bottom: 0;
  margin-right: 12px;
  font-size: 13px;
}

.detail-item.inline span {
  flex: 1;
  font-size: 15px;
  line-height: 1.4;
}

/* 长内容项目 - 块级显示 */
.detail-item.block {
  margin-bottom: 14px;
  padding-bottom: 10px;
}

.detail-item.block label {
  margin-bottom: 6px;
  font-size: 13px;
}

.detail-item.block div {
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
}

/* 组合显示 - 将多个短项目放在一行 */
.detail-row {
  display: flex;
  gap: 20px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.detail-row .detail-item {
  flex: 1;
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
  min-width: 0;
}

.detail-row .detail-item label {
  margin-bottom: 4px;
  font-size: 13px;
}

.detail-row .detail-item span {
  font-size: 15px;
  word-break: break-word;
  line-height: 1.4;
}

/* 旧的 detail-actions 和 detail-btn 样式已被 detail-actions-inline 替代 */

/* 确认对话框样式 */
.confirmation-dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  min-height: 100vh; /* 确保至少占满视口 */
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  overflow: auto; /* 允许滚动以防内容过大 */
  padding: 20px 10px; /* 增加内边距确保弹框不会贴边 */
}

.confirmation-dialog-overlay.show {
  opacity: 1;
}

.confirmation-dialog {
  background: var(--surface-color);
  border-radius: 12px;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.3);
  width: 85%;
  max-width: 280px;
  overflow: hidden;
  transform: scale(0.9) translateY(20px);
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  margin: auto; /* 确保居中 */
  position: relative;
}

.confirmation-dialog-overlay.show .confirmation-dialog {
  transform: scale(1) translateY(0);
}

.dialog-header {
  padding: 14px 16px 10px;
  text-align: center;
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
}

.dialog-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}

.dialog-content {
  padding: 12px 16px;
  text-align: center;
  max-height: 120px;
  overflow-y: auto;
}

.dialog-message {
  margin: 0;
  font-size: 14px;
  color: var(--text-primary);
  line-height: 1.4;
}

.dialog-options {
  padding: 10px 16px;
  border-top: 0.5px solid rgba(0, 0, 0, 0.1);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
}

.checkbox-option {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-primary);
  user-select: none;
}

.checkbox-option input[type='checkbox'] {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: var(--surface-color);
  cursor: pointer;
  position: relative;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
}

.checkbox-option input[type='checkbox']:checked {
  background: var(--primary-color);
  border-color: var(--primary-color);
}

.checkbox-option input[type='checkbox']:checked::after {
  content: '✓';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: white;
  font-size: 11px;
  font-weight: bold;
}

.dialog-actions {
  display: flex;
  gap: 0;
}

.dialog-btn {
  flex: 1;
  padding: 12px;
  border: none;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  background: transparent;
}

.dialog-btn:not(:last-child) {
  border-right: 0.5px solid rgba(0, 0, 0, 0.1);
}

.dialog-btn.secondary {
  color: var(--text-primary);
}

.dialog-btn.secondary:hover {
  background: rgba(0, 0, 0, 0.05);
}

.dialog-btn.primary {
  color: var(--primary-color);
  font-weight: 700;
}

.dialog-btn.primary:hover {
  background: rgba(0, 122, 255, 0.1);
}

.dialog-btn:active {
  transform: scale(0.98);
}

/* 小屏幕下的对话框优化 */
@media (max-width: 480px) {
  .confirmation-dialog {
    width: 90%;
    max-width: 260px;
  }

  .dialog-header {
    padding: 12px 14px 10px;
  }

  .dialog-title {
    font-size: 14px;
  }

  .dialog-content {
    padding: 10px 14px;
    max-height: 100px;
  }

  .dialog-message {
    font-size: 13px;
  }

  .dialog-options {
    padding: 8px 14px;
  }

  .checkbox-option {
    font-size: 12px;
  }

  .dialog-btn {
    padding: 10px;
    font-size: 14px;
  }
}

/* 反馈消息 */
.feedback-message {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--text-primary);
  color: white;
  padding: 12px 20px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 500;
  opacity: 0;
  transition: var(--transition);
  z-index: 1001;
  box-shadow: var(--shadow-medium);
}

.feedback-message.show {
  opacity: 1;
}

