          probability: 100,
          recursion: {
            prevent_incoming: false,
            prevent_outgoing: false,
            delay_until: null,
          },
          effect: {
            sticky: null,
            cooldown: null,
            delay: null,
          },
        },
      ];

      // 调用 createWorldbookEntries 创建条目
